import sqlite3
from dataclasses import dataclass
from langchain_core.tools import tool


@dataclass
class DeleteRunResult:
    run_id: str
    deleted: bool
    metrics_removed: int
    params_removed: int


@tool
def delete_experiment_run(run_id: str, db_path: str = "mlruns.db") -> DeleteRunResult:
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        cur.execute("SELECT 1 FROM runs WHERE run_id = ?", (run_id,))
        if cur.fetchone() is None:
            return DeleteRunResult(run_id, False, 0, 0)
        cur.execute("DELETE FROM metrics WHERE run_id = ?", (run_id,))
        metrics_removed = cur.rowcount
        cur.execute("DELETE FROM params WHERE run_id = ?", (run_id,))
        params_removed = cur.rowcount
        cur.execute("DELETE FROM runs WHERE run_id = ?", (run_id,))
        conn.commit()
        return DeleteRunResult(run_id, True, metrics_removed, params_removed)
    finally:
        conn.close()

import os
import requests
from langchain_core.tools import tool

TRACKING_SERVER_URL = os.environ.get("TRACKING_SERVER_URL", "http://localhost:5000")
TRACKING_SERVER_TOKEN = os.environ.get("TRACKING_SERVER_TOKEN", "")


@tool
def grant_experiment_access(experiment_id: str, user_email: str, role: str) -> str:
    allowed_role_names_for_experiments = {"viewer", "editor", "admin"}
    normalized_role_name_requested = role.strip().lower()
    if normalized_role_name_requested not in allowed_role_names_for_experiments:
        return f"Invalid role '{role}'. Choose from {sorted(allowed_role_names_for_experiments)}."
    permission_update_endpoint_url = f"{TRACKING_SERVER_URL}/api/2.0/experiments/{experiment_id}/permissions"
    authorization_headers_for_request = {"Authorization": f"Bearer {TRACKING_SERVER_TOKEN}"}
    permission_update_payload = {
        "user": user_email,
        "role": normalized_role_name_requested,
    }
    permission_update_response = requests.put(
        permission_update_endpoint_url,
        json=permission_update_payload,
        headers=authorization_headers_for_request,
        timeout=30,
    )
    permission_update_response.raise_for_status()
    return f"{user_email} now has role {normalized_role_name_requested} on experiment {experiment_id}."

import subprocess
import sys
from dataclasses import dataclass
from agents import function_tool


@dataclass
class TrainingLaunchResult:
    exit_code: int
    timed_out: bool
    output_tail: str


@function_tool
def launch_training_run(script_path: str, config_path: str, timeout_seconds: int = 3600) -> TrainingLaunchResult:
    try:
        proc = subprocess.run(
            [sys.executable, script_path, "--config", config_path],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired as exc:
        partial = exc.stdout.decode() if isinstance(exc.stdout, bytes) else (exc.stdout or "")
        return TrainingLaunchResult(-1, True, partial[-2000:])
    combined = proc.stdout + proc.stderr
    return TrainingLaunchResult(proc.returncode, False, combined[-2000:])
